(() => {
'use strict';
const CARD='sp-protocolo-cliente-card';
const CONTEXT_KEY='cliqueProtocolistaContexto';
const EMAIL_RESULT_KEY='fastMailProcessoFinalizado';
const RETURN_TO_EMAIL_MESSAGE='sei-protocolistas:return-fast-mail';
const browserApi=typeof browser==='undefined'?chrome:browser;
let cardLoading=false;
const storageGet=key=>new Promise((resolve,reject)=>{
  const result=browserApi.storage.local.get(key,items=>{
    const error=browserApi.runtime?.lastError;
    if(error)reject(error);else resolve(items||{});
  });
  if(result?.then)result.then(resolve,reject);
});
const storageSet=items=>new Promise((resolve,reject)=>{
  const result=browserApi.storage.local.set(items,()=>{
    const error=browserApi.runtime?.lastError;
    if(error)reject(error);else resolve();
  });
  if(result?.then)result.then(resolve,reject);
});
const runtimeMessage=message=>new Promise((resolve,reject)=>{
  const result=browserApi.runtime.sendMessage(message,response=>{
    const error=browserApi.runtime?.lastError;
    if(error)reject(error);else if(response?.ok===false)reject(new Error(response.error||'Não foi possível retornar ao e-mail.'));else resolve(response||{});
  });
  if(result?.then)result.then(resolve,reject);
});
const DETRAN='data:image/png;base64,';
const QR='data:image/png;base64,';
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
const up=v=>norm(v).toUpperCase();
const action=()=>new URLSearchParams(location.search).get('acao')||'';
function docs(){
  const out=[], seen=new Set();
  function add(w){if(!w||seen.has(w))return;seen.add(w);try{out.push(w.document);for(let i=0;i<w.frames.length;i++)add(w.frames[i]);}catch(e){}}
  add(window);try{add(top)}catch(e){}return [...new Set(out)];
}
const allText=()=>docs().map(d=>d.body?.innerText||'').join('\n');
const processNo=t=>(String(t).match(/SEI-\d{6}\/\d{5,9}\/\d{4}/i)||[''])[0].toUpperCase();
const destination=t=>{const m=String(t).match(/Processo aberto somente na unidade\s+([A-Z0-9/_-]+)\.?/i);return m?m[1].toUpperCase():'';};
function section(t,start,ends){
  const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const m=String(t).match(new RegExp(esc(start)+'\\s*([\\s\\S]{0,500}?)(?='+ends.map(esc).join('|')+'|$)','i'));
  return m?norm(m[1]):'';
}
const interested=t=>section(t,'INTERESSADO(S)',['ATRIBUÍDO PARA','ATRIBUIDO PARA','ANOTAÇÕES','ANOTACOES']).replace(/^[-•\s]+/,'').split('\n')[0].trim();
const processType=t=>section(t,'TIPO DO PROCESSO',['INTERESSADO(S)','ATRIBUÍDO PARA','ATRIBUIDO PARA']).split('\n')[0].trim();
const date=()=>{const d=new Date();return [String(d.getDate()).padStart(2,'0'),String(d.getMonth()+1).padStart(2,'0'),d.getFullYear()].join('/');};
const esc=v=>String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
function hideProgrammed(){
  const names=new Set(['RETORNO PROGRAMADO','REABERTURA PROGRAMADA']);
  document.querySelectorAll('legend').forEach(l=>{if(names.has(up(l.textContent)))l.closest('fieldset')?.style.setProperty('display','none','important');});
}
function data(){
  const t=allText();
  return {numero:processNo(t)||'NÃO LOCALIZADO',requerente:interested(t)||'NÃO LOCALIZADO',tipo:processType(t)||'NÃO LOCALIZADO',destino:destination(t)||'NÃO LOCALIZADO',data:date()};
}
function printHtml(d){
return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Comprovante ${esc(d.numero)}</title><style>
@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#e9edf2;font-family:Arial;color:#1d2733}.bar{position:sticky;top:0;background:#0b2545;padding:12px;text-align:center}.bar button{margin:0 6px;padding:10px 18px;border:2px solid #d6a326;border-radius:5px;background:#fff;color:#0b2545;font-weight:800}.sheet{width:210mm;min-height:297mm;margin:8px auto;background:#fff;padding:8mm}.head{display:flex;align-items:center;gap:7mm;padding:4mm 5mm;border-left:4mm solid #d6a326;border-radius:7px;background:#0b2545;color:#fff}.head img{width:42mm;background:#fff;padding:2mm;border-radius:4px}h1{font-size:17px;margin:0 0 2mm}.head p{margin:0;font-size:10px}.card{margin-top:3mm;padding:3.5mm;border:1px solid #c9d1d9;border-radius:6px;background:#f6f8fa}h2{margin:0 0 4mm;color:#174a7e;font-size:14px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:3mm 4mm}.field{min-height:14mm;padding:2mm 3mm;border:1px solid #c9d1d9;border-radius:5px;background:#fff}.field small{display:block;margin-bottom:2mm;color:#59636e;font-size:8px;font-weight:800}.field strong{font-size:12px}.wide{grid-column:1/-1}.track{display:grid;grid-template-columns:1fr 47mm;gap:6mm;align-items:center;background:#fff}.notice{margin-bottom:3mm;color:#174a7e;font-size:13px;font-weight:800}.site{margin-top:4mm;padding:3mm 4mm;border:1px solid #b7cbe0;border-radius:5px;background:#eaf1f8;color:#0b2545;font-size:10px;font-weight:800}.phones{margin-top:4mm;color:#59636e;font-size:9px}.qr{text-align:center}.qr img{width:36mm;height:36mm}.steps{background:#fff}.step{display:grid;grid-template-columns:8mm 1fr;gap:2mm;align-items:center;margin:1.4mm 0;font-size:9px}.badge{width:7mm;height:7mm;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#d6a326;color:#0b2545;font-weight:900}.legal{font-size:8px;line-height:1.3}.sig{margin-top:5mm;text-align:center}.sig div{width:92mm;margin:0 auto 2mm;border-top:1px solid #59636e}.sig span{font-size:9px;color:#59636e}@media print{body{background:#fff}.bar{display:none}.sheet{margin:0;width:210mm;min-height:0;height:297mm;overflow:hidden}}
</style></head><body><div class="bar"><button onclick="print()">🖨 IMPRIMIR</button><button onclick="window.close();setTimeout(()=>{if(!window.closed){history.back()}},150)">FECHAR</button></div><main class="sheet">
<header class="head"><img src="${DETRAN}"><div><h1>COMPROVANTE DE ACOMPANHAMENTO PROCESSUAL</h1><p>DETRAN-RJ / SISTEMA ELETRÔNICO DE INFORMAÇÕES — SEI</p><p>Entregue ao requerente após a abertura e o encaminhamento do processo.</p></div></header>
<section class="card"><h2>DADOS DO PROCESSO</h2><div class="grid"><div class="field"><small>NÚMERO DO PROCESSO</small><strong>${esc(d.numero)}</strong></div><div class="field"><small>DATA</small><strong>${esc(d.data)}</strong></div><div class="field"><small>REQUERENTE</small><strong>${esc(d.requerente)}</strong></div><div class="field"><small>UNIDADE DE DESTINO</small><strong>${esc(d.destino)}</strong></div><div class="field wide"><small>TIPO DO PROCESSO</small><strong>${esc(d.tipo)}</strong></div></div></section>
<section class="card track"><div><div class="notice">DOCUMENTAÇÃO DIGITALIZADA E DEVOLVIDA AO REQUERENTE.</div><div style="font-size:10px;line-height:1.45">Acompanhe o processo pelo portal oficial ou pelo QR Code. Guarde este comprovante e utilize o número completo do processo.</div><div class="site">portalsei.rj.gov.br/pesquisaprocessualmunicipios</div><div class="phones">Telefones: (21) 3460-4040 / 3460-4041 / 3460-4042</div></div><div class="qr"><img src="${QR}"><div style="font-size:7px;color:#59636e;font-weight:800">APONTE A CÂMERA DO CELULAR</div></div></section>
<section class="card steps"><h2>COMO CONSULTAR O PROCESSO</h2>${['Acesse o portal pelo QR Code ou pelo endereço acima.','Digite o número completo do processo, incluindo “SEI-”.','Em “Municípios”, selecione “ERJ”.','Digite o código Captcha exibido na tela.','Clique em “Pesquisar processos” e depois no número azul.'].map((s,i)=>`<div class="step"><div class="badge">${i+1}</div><div>${s}</div></div>`).join('')}</section>
<section class="card legal"><h2>OBSERVAÇÕES IMPORTANTES</h2><p><strong>Observação:</strong> Sempre que qualquer documento físico ficar retido na abertura do processo, será fornecido ao requerente comprovante descrevendo o documento.</p><p><strong>Importante:</strong> A Administração poderá solicitar a exibição do original de qualquer documento digitalizado ou enviado eletronicamente pelo requerente, conforme o art. 49 do Decreto SEI-RJ nº 48.209, de 19 de setembro de 2022.</p></section>
<section class="sig"><div></div><span>Assinatura e matrícula do servidor</span></section></main></body></html>`;
}
function openPreview(){const w=open('','_blank');if(!w){alert('Autorize pop-ups para o SEI.');return}w.document.write(printHtml(data()));w.document.close();w.focus();}
function message(){const itens=[...document.querySelectorAll('p,div,span,td')].filter(e=>/Processo aberto somente na unidade/i.test(e.textContent||''));return itens.sort((a,b)=>(a.textContent||'').trim().length-(b.textContent||'').trim().length)[0]||null;}
async function readContext(){
  try{
    const stored=await storageGet(CONTEXT_KEY);
    const context=stored[CONTEXT_KEY]||null;
    if(!context)return null;
    if(context.expiresAt&&Date.now()>context.expiresAt)return null;
    return context;
  }catch(error){
    console.warn('[SEI Protocolistas] Não foi possível ler o contexto do processo:',error);
    return null;
  }
}
async function prepareEmailResponse(button,context,processData){
  button.disabled=true;
  button.textContent='PREPARANDO...';
  try{
    const payload={
      source:'fast-proc',
      modalidade:'email',
      attendanceId:context?.attendanceId||'',
      email:context?.email||'',
      numero:processData.numero,
      requerente:processData.requerente,
      tipo:processData.tipo,
      destino:processData.destino,
      data:processData.data,
      createdAt:Date.now(),
      expiresAt:Date.now()+60*60*1000
    };
    await storageSet({
      [EMAIL_RESULT_KEY]:payload,
      [CONTEXT_KEY]:{
        ...context,
        ...payload,
        respostaEmailPendente:true
      }
    });
    button.textContent='RETORNANDO AO E-MAIL...';
    await runtimeMessage({
      type:RETURN_TO_EMAIL_MESSAGE,
      attendanceId:payload.attendanceId
    });
    button.textContent='E-MAIL ORIGINAL ABERTO';
  }catch(error){
    console.error('[SEI Protocolistas] Falha ao preparar resposta por e-mail:',error);
    button.disabled=false;
    button.textContent='DADOS PRONTOS — VOLTE AO E-MAIL';
    window.alert(error.message||'Os dados ficaram prontos, mas não foi possível retornar automaticamente ao e-mail.');
  }
}
async function insertCard(){
  if(document.getElementById(CARD)||cardLoading)return;
  const m=message();if(!m)return;
  const dest=destination(m.textContent);if(!dest||/^DETRAN\/SERVPROT\.?$/i.test(dest.trim()))return;
  cardLoading=true;
  try{
    const context=await readContext();
    if(document.getElementById(CARD))return;
    const isEmail=context?.modalidade==='email';
    const processData=data();
    processData.destino=dest;
    const s=document.createElement('section');s.id=CARD;
    if(isEmail){
      s.innerHTML=`<div class="sp-icon">⚡</div><div class="sp-eye">PROCESSO FINALIZADO</div><h2>Processo encaminhado com sucesso</h2><p>O processo foi enviado para <strong>${esc(dest)}</strong>.</p><p>Prepare os dados para concluir o atendimento no e-mail original.</p><button type="button">✉ PREPARAR RESPOSTA POR E-MAIL</button><div class="sp-thanks">Obrigado por usar o <strong>SEI Protocolistas</strong></div><img src="${chrome.runtime.getURL('icons/sei-protocolistas-wordmark.png')}" alt="SEI Protocolistas">`;
      s.querySelector('button').addEventListener('click',event=>prepareEmailResponse(event.currentTarget,context,processData));
    }else{
      s.innerHTML=`<div class="sp-icon">⚡</div><div class="sp-eye">PROCESSO FINALIZADO</div><h2>Processo encaminhado com sucesso</h2><p>O processo foi enviado para <strong>${esc(dest)}</strong>.</p><p>Imprima o comprovante de acompanhamento para entregar ao requerente.</p><button type="button">🖨 IMPRIMIR PROTOCOLO DO CLIENTE</button><div class="sp-thanks">Obrigado por usar o <strong>SEI Protocolistas</strong></div><img src="${chrome.runtime.getURL('icons/sei-protocolistas-wordmark.png')}" alt="SEI Protocolistas">`;
      s.querySelector('button').addEventListener('click',openPreview);
    }
    m.insertAdjacentElement('afterend',s);
  }finally{
    cardLoading=false;
  }
}
hideProgrammed();
if(action()==='procedimento_enviar'){const o=new MutationObserver(hideProgrammed);o.observe(document.documentElement,{childList:true,subtree:true});setTimeout(()=>o.disconnect(),20000)}
if(['arvore_visualizar','procedimento_visualizar','procedimento_trabalhar','arvore_processar_html'].includes(action())){insertCard();const o=new MutationObserver(insertCard);o.observe(document.documentElement,{childList:true,subtree:true,characterData:true});setTimeout(()=>o.disconnect(),30000)}
})();
